import sys

import anndata as ad
import numpy as np
from scipy import sparse


def main(input_h5ad: str, result_path: str, diagnostics_path: str) -> None:
    adata = ad.read_h5ad(input_h5ad)

    required_obs = {"bulk_labels", "percent_mito"}
    missing_obs = sorted(required_obs.difference(adata.obs.columns))
    if missing_obs:
        raise ValueError(f"Missing observation columns: {missing_obs}")

    gene_counts = {gene: int(np.sum(adata.var_names == gene)) for gene in ("SRM", "MRPS21")}
    if gene_counts != {"SRM": 1, "MRPS21": 1}:
        raise ValueError(f"Target genes must each occur exactly once: {gene_counts}")

    percent_mito = np.asarray(adata.obs["percent_mito"], dtype=np.float64)
    label_mask = np.asarray(adata.obs["bulk_labels"].astype(str) == "CD19+ B")
    mito_mask = percent_mito < 0.04
    selected_mask = label_mask & mito_mask

    selected = adata[selected_mask, ["SRM", "MRPS21"]].X
    if sparse.issparse(selected):
        selected = selected.toarray()
